(() => {
 if(document.querySelector('.about-chat'))return;
 const panel=document.createElement('aside');panel.className='about-chat';panel.id='about-chat';panel.inert=true;panel.setAttribute('role','dialog');panel.setAttribute('aria-label','Know more about Vinny');
 panel.innerHTML='<header><div><span class="chat-mark" aria-hidden="true">✳</span><h2>Know more about me</h2></div><button type="button" class="chat-close" aria-label="Close chat"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button></header><div class="chat-space"><span class="chat-spark" aria-hidden="true">✳</span><h3>A little more Vinny.</h3><p>My work, my approach, and the person behind the pixels.</p></div><div class="chat-composer"><label for="about-chat-prompt">Ask me something</label><div><input id="about-chat-prompt" placeholder="What would you like to know?" disabled><button type="button" aria-label="Send message, coming soon" disabled>↑</button></div><small>Conversation coming soon.</small></div>';
 document.body.append(panel);let previous=null;const background=new Map();const mobile=matchMedia('(max-width:760px)');
 panel.addEventListener('transitionend',e=>{if(e.target===panel&&e.propertyName==='transform')window.dispatchEvent(new Event('resize'))});
 async function open(trigger){previous=trigger;await window.portfolioCloseMobileMenu?.();document.querySelectorAll('.contact-dropdown.is-open').forEach(e=>{e.classList.remove('is-open');e.querySelector('[data-contact-trigger]')?.setAttribute('aria-expanded','false');e.querySelector('.contact-options').inert=true});document.querySelectorAll('.top-contact.is-open').forEach(e=>e.classList.remove('is-open'));document.querySelectorAll('.about-top-nav details').forEach(e=>e.open=false);panel.inert=false;if(mobile.matches){panel.setAttribute('aria-modal','true');[...document.body.children].filter(e=>e!==panel&&!['SCRIPT','STYLE','LINK'].includes(e.tagName)).forEach(e=>{background.set(e,e.inert);e.inert=true})}document.body.classList.add('chat-open');document.querySelectorAll('[data-about-chat]').forEach(e=>e.setAttribute('aria-expanded','true'));panel.querySelector('.chat-close').focus({preventScroll:true});}
 function close(){background.forEach((value,e)=>e.inert=value);background.clear();panel.removeAttribute('aria-modal');document.body.classList.remove('chat-open');panel.inert=true;document.querySelectorAll('[data-about-chat]').forEach(e=>e.setAttribute('aria-expanded','false'));previous?.focus({preventScroll:true});}
 panel.querySelector('.chat-close').addEventListener('click',close);
 document.addEventListener('keydown',e=>{if(e.key==='Tab'&&mobile.matches&&document.body.classList.contains('chat-open')){e.preventDefault();panel.querySelector('.chat-close').focus()}if(e.key==='Escape'&&document.body.classList.contains('chat-open')){e.preventDefault();close()}});
 document.addEventListener('click',e=>{const t=e.target.closest('[data-about-chat]');if(t){e.preventDefault();open(t)}});
 function addTriggers(){document.querySelectorAll('.contact-options,.top-contact-options,.about-top-nav details>div').forEach(menu=>{if(menu.querySelector('[data-about-chat]'))return;const button=document.createElement('button');button.type='button';button.className='chat-menu-trigger';button.dataset.aboutChat='';button.setAttribute('aria-controls','about-chat');button.setAttribute('aria-expanded','false');button.innerHTML='<span>Know more about me</span><small>A little conversation</small>';menu.append(button)});}
 addTriggers();new MutationObserver(addTriggers).observe(document.body,{childList:true,subtree:true});
 if(document.body.classList.contains('about-page')){const h1=document.querySelector('main h1');if(h1){const button=document.createElement('button');button.type='button';button.className='about-chat-entry';button.dataset.aboutChat='';button.setAttribute('aria-controls','about-chat');button.setAttribute('aria-expanded','false');button.textContent='Know more about me';h1.insertAdjacentElement('afterend',button)}}
})();
